script:
(function () {
  'use strict';
  // Interest-only ARM: interest-only payments while the start rate is fixed, then a recast.
  //   Interest-only payment = balance x rate / 12. At the end of the interest-only period the whole
  //   balance (nothing has been repaid) is amortized over the months left: M = B * i / (1 - (1 + i)^-n),
  //   i = rate / 12 (M = B / n at 0%). The rate adjusts at the end of the fixed period and then every
  //   6 or 12 months toward index + margin (the index moving by the expected change at each
  //   adjustment), limited by the first and periodic caps, the lifetime cap (start + cap) and the
  //   floor. The payment is re-amortized whenever the rate changes after the recast.
  //   Worst case: the rate rises by the full cap at every adjustment up to the lifetime cap.
  //   Payment shock = first amortizing payment - interest-only payment.
  // Verified in Node (scratchpad mtg6/tests/ioa.test.js): $400,000 at 6.25% -> $2,083.33 interest
  //   only; 30-year 7/6 loan, index 4% + margin 2.75% with 5/1/5 caps -> recast at 6.75% over 276
  //   months = $2,857.65 (closed form); worst case 11.25% from payment 85 -> $4,058.97 (closed form);
  //   a 5-year interest-only period inside a 7-year fixed period recasts at the start rate to
  //   $2,638.68 (closed form over 300 months); the balance ends at $0; 0% rates give $0 then
  //   $1,449.28 (= $400,000 / 276); blank and negative inputs show an error, never NaN.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var whole = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  // --- pure ---
  function payment(balance, annualPct, months) {
    if (months <= 0 || balance <= 0) return 0;
    var i = annualPct / 1200;
    if (i === 0) return balance / months;
    return balance * i / (1 - Math.pow(1 + i, -months));
  }

  // o: loan, months, start, fixedMonths, ioMonths, every, index, margin, idxChange, firstCap, perCap, lifeCap, floor
  function ioArm(o) {
    var rate = o.start, bal = o.loan, adj = 0, pay = 0, ceiling = o.start + o.lifeCap;
    var months = [], totalInterest = 0, firstAm = null, maxPay = 0, maxRate = rate;
    for (var m = 0; m < o.months; m++) {
      var changed = false;
      if (m >= o.fixedMonths && (m - o.fixedMonths) % o.every === 0) {
        adj++;
        var target = o.index + o.idxChange * adj + o.margin;
        var cap = adj === 1 ? o.firstCap : o.perCap;
        target = Math.max(rate - cap, Math.min(rate + cap, target));
        target = Math.max(0, Math.max(o.floor, Math.min(ceiling, target)));
        if (Math.abs(target - rate) > 1e-12) { rate = target; changed = true; }
      }
      var interest = bal * rate / 1200, p;
      if (m < o.ioMonths) p = interest;
      else {
        if (m === o.ioMonths || changed) pay = payment(bal, rate, o.months - m);
        p = Math.min(pay, bal + interest);
        if (m === o.months - 1) p = bal + interest;
        if (firstAm === null) firstAm = { month: m + 1, pay: p, rate: rate };
      }
      bal = bal + interest - p;
      if (Math.abs(bal) < 0.005) bal = 0;
      totalInterest += interest;
      if (p > maxPay) maxPay = p;
      if (rate > maxRate) maxRate = rate;
      months.push({ rate: rate, pay: p, interest: interest, principal: p - interest, bal: bal });
    }
    return { months: months, totalInterest: totalInterest, firstAm: firstAm, maxPay: maxPay, maxRate: maxRate,
             ioPay: o.ioMonths > 0 ? months[0].pay : null };
  }
  // --- end pure ---

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }
  function read(id, blank) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blank;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }
  function cell(row, text) { var td = document.createElement('td'); td.textContent = text; row.appendChild(td); }
  function pct(v) { return (Math.round(v * 1000) / 1000) + '%'; }

  var OUT = ['ioaIoPay', 'ioaRecastPay', 'ioaShock', 'ioaWorstPay', 'ioaWorstShock', 'ioaMaxPay', 'ioaRecastWhen', 'ioaBalance',
             'ioaInterest', 'ioaWorstInterest', 'ioaFully', 'ioaShockNote'];
  function clearAll() { OUT.forEach(function (id) { setText(id, '–'); }); el('ioaSchedule').textContent = ''; }

  function update() {
    var loan = read('ioaLoan', NaN), start = read('ioaStart', NaN), years = parseInt(el('ioaTerm').value, 10),
        fixedYears = parseInt(el('ioaFixed').value, 10), every = parseInt(el('ioaEvery').value, 10),
        ioSel = el('ioaIoPeriod').value, index = read('ioaIndex', NaN), margin = read('ioaMargin', NaN),
        idxChange = read('ioaChange', 0), firstCap = read('ioaFirstCap', Infinity), perCap = read('ioaPerCap', Infinity),
        lifeCap = read('ioaLifeCap', Infinity), floor = read('ioaFloor', 0);
    var months = years * 12, fixedMonths = fixedYears * 12;
    var ioMonths = ioSel === 'same' ? fixedMonths : parseInt(ioSel, 10) * 12;
    var msg = '';
    if (isNaN(loan) || loan <= 0) msg = 'Enter a loan amount greater than $0.';
    else if (isNaN(start) || start < 0 || start > 30) msg = 'Enter a start rate from 0% to 30%.';
    else if (isNaN(index) || index < 0 || index > 30 || isNaN(margin) || margin < 0 || margin > 15) msg = 'Enter an index from 0% to 30% and a margin from 0% to 15%.';
    else if (isNaN(idxChange) || Math.abs(idxChange) > 5) msg = 'Enter an index change per adjustment between -5% and 5%.';
    else if ([firstCap, perCap, lifeCap, floor].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Caps and floor cannot be negative. Leave a cap blank if the loan has none.';
    else if (fixedMonths >= months) msg = 'The fixed-rate period must be shorter than the loan term.';
    else if (ioMonths >= months) msg = 'The interest-only period must be shorter than the loan term.';
    el('ioaError').hidden = !msg;
    el('ioaError').textContent = msg;
    if (msg) { clearAll(); return; }

    var base = { loan: loan, months: months, start: start, fixedMonths: fixedMonths, ioMonths: ioMonths, every: every, index: index,
                 margin: margin, idxChange: idxChange, firstCap: firstCap, perCap: perCap, lifeCap: lifeCap, floor: floor };
    var s = ioArm(base);
    // Worst case: the index jumps far enough that every adjustment hits its cap.
    var w = ioArm(Object.assign({}, base, { idxChange: 100 }));
    var io = s.ioPay || 0;
    setText('ioaIoPay', s.ioPay === null ? 'None' : money.format(io));
    setText('ioaRecastPay', money.format(s.firstAm.pay));
    setText('ioaShock', '+' + money.format(s.firstAm.pay - io) + (io > 0 ? ' (' + ((s.firstAm.pay / io - 1) * 100).toFixed(0) + '%)' : ''));
    setText('ioaWorstPay', money.format(w.firstAm.pay) + ' at ' + pct(w.firstAm.rate));
    setText('ioaWorstShock', '+' + money.format(w.firstAm.pay - io) + (io > 0 ? ' (' + ((w.firstAm.pay / io - 1) * 100).toFixed(0) + '%)' : ''));
    setText('ioaMaxPay', money.format(w.maxPay) + ' at ' + pct(w.maxRate));
    var yr = Math.floor((s.firstAm.month - 1) / 12) + 1;
    setText('ioaRecastWhen', 'Payment ' + s.firstAm.month + ' (year ' + yr + ')');
    setText('ioaBalance', money.format(ioMonths > 0 ? s.months[ioMonths - 1].bal : loan));
    setText('ioaInterest', whole.format(s.totalInterest));
    setText('ioaWorstInterest', whole.format(w.totalInterest));
    setText('ioaFully', pct(index + margin));
    setText('ioaShockNote', 'When the interest-only period ends you start repaying the full ' + whole.format(loan) + ' over ' +
      ((months - ioMonths) / 12).toFixed(ioMonths % 12 ? 1 : 0) + ' years instead of ' + years +
      '. Even if rates do not rise, plan for a payment of about ' + money.format(s.firstAm.pay) + ', and up to ' + money.format(w.firstAm.pay) +
      ' if the first adjustment hits its cap.');

    var body = el('ioaSchedule');
    body.textContent = '';
    for (var y = 0; y < years; y++) {
      var slice = s.months.slice(y * 12, y * 12 + 12), ws = w.months.slice(y * 12, y * 12 + 12);
      if (!slice.length) break;
      var intY = 0, prinY = 0;
      slice.forEach(function (mo) { intY += mo.interest; prinY += mo.principal; });
      var end = slice[slice.length - 1];
      var tr = document.createElement('tr');
      cell(tr, String(y + 1));
      cell(tr, pct(end.rate));
      cell(tr, money.format(end.pay));
      cell(tr, whole.format(intY));
      cell(tr, whole.format(prinY));
      cell(tr, whole.format(end.bal));
      cell(tr, money.format(ws[ws.length - 1].pay));
      body.appendChild(tr);
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('ioaForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
